quests[55651] = { id = 55651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Mechagon!", description = "Whatever's waiting for us on the shores of Mechagon, we're going to be ready for it with this crew.\n\nI don't hold any misconceptions about how that crazy king is going to welcome us. Guns blazin', I'm sure.\n\nSo we're going in quietly on this submarine. Low profile'll keep us all safe.\n\nWhen you're ready to go, talk to Captain Krooz.", completion = "Don't let the grass fool ya. Look at those bots on the shoreline. That city up ahead. That constant buzz of machinery and smog in the air.\n\nThis place is a technological gold mine.", objectives = "Talk with Captain Krooz to travel to Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55652] = { id = 55652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prospectus Bay", description = "Looks like we made it in unnoticed.\n\nSkaggit's crew can set up shop on that beach, but we gotta make sure it's safe for 'em to land first.\n\nLet's do a quick flyover to scout out how we're going to crack this place wide open.\n\nThat town up on the hill looks promising...", completion = "We'll own this whole island in no time.", objectives = "Jetpack into Prospectus Bay with Gazlowe and the crew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55655] = { id = 55655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55657] = { id = 55657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Shadow of Crimson Wings", description = "It is unlike Alexstrasza to remain out of contact for so long, particularly when the very essences of the dragonflights' power are being made manifest. \n\nWhile our allies here tend to the injured, we must seek out the Life-Binder at once.\n\nWhen you are ready, we shall ride to the Vermillion Redoubt together.", progress = "We must rely on your aid once more, champion.", completion = "We owe you a great deal of gratitude. You have the support of the red dragonflight in your efforts to save Azeroth.", objectives = "Speak with Kalecgos to fly to the Vermillion Redoubt, locate Alexstrasza and discover the source of the threat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55658] = { id = 55658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clues Abound", description = "Before King Mechagon claimed this island, someone else lived here.  Buried beneath this filth and garbage is the history of a forgotten people. With your help, we shall learn about these previous inhabitants.\n\nSir Finley has marked a location where he's seen unusual artifacts. Meet him there and see if you can discover any clues.", progress = "Get to it, history is waiting for you!", completion = "Good show! We'll get to the bottom of this mystery in no time!", objectives = "Discover a clue about the island's history.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55659] = { id = 55659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Sundering", description = "It's not every day that you encounter the remnants of a lost civilization beneath the ocean!\n\nI never would have imagined that I'd have the opportunity to explore the lost city of Nazjatar... and on solid ground at that!\n\nThere are many secrets here to uncover. If you come across any ancient highborne artifacts, please bring them to me. These relics could provide us with valuable clues regarding the mysteries of the Great Sundering.\n\nI feel as though we are barely scratching the surface so far...", progress = "Whatever mysteries were hidden here beneath the ocean are now waiting to be revealed!", completion = "Excellent work! Look at all of these highborne relics you've found! I will begin examining them at once.", objectives = "Collect 10 Highborne Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55660] = { id = 55660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Trials", objectives = "Good luck!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55661] = { id = 55661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Venomous With Venom", description = "There are many uses for the poison of the snapdragons.\n\nImmediate use would be to create antivenin for healing, or harvesting poison for attacking the naga.\n\nLet's get to the root of the issue, literally.\n\nUse some collected venom against a Terrormaw to weaken it. Kill one and bring me their fangs.\n\nI think we can come up with something handy from there.", progress = "Did you get the fangs?", completion = "Need to be careful not to scratch myself with these.\n\nWith a little learning, we should be able to create an antidote... and maybe a weapon of our own!", objectives = "Use collected venom to weaken and kill a Snapdragon Terrormaw for their fangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55662] = { id = 55662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", progress = "<The chest is locked and requires a key.>", completion = "<The magical barrier dissipates as you insert the key.>", objectives = "Locate the key to the Arcane Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55663] = { id = 55663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Controller", description = "It is too late for me, my friends.\n\nThe Controllers work us and work us and we have no rest.\n\nWe have lost so many. \n\nPlease, free the others! Don't let them share my fate!", completion = "Every kelfin we set free, makes the naga a little weaker.\n\nI heal who I can.", objectives = "Free the slaves and destroy the Merciless Controller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55664] = { id = 55664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blow to Morale", description = "This place is the source of all of our corruption. \n\nThe kelfin are taken and broken here. \n\nHit them where it hurts. Break their power, kill every naga you see, wreak havoc!\n\nEvery little crack we make, weakens their foundation.", progress = "Did you damage their morale?", completion = "It's going to take them a while to clean that up, {name}!\n\nI love watching them scurry.", objectives = "Disrupt all activities in the Shirakess Repository.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55665] = { id = 55665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Garden", description = "Look, {name}, I know we have bigger battles ahead, but these gardens are horrific.\n\nInnocent creatures captured and imprisoned for the naga's amusement. \n\nThey bring them out, torture them, change them, break them... you get the idea.\n\nHelp me free those the naga have taken, and punish them for their hubris!", progress = "Were you able to wreak some havoc in there?", completion = "I'm pretty sure I heard an otter giggle as it ran past. \n\nYour fighting skills were most rad.", objectives = "Kill naga and release the poor tortured creatures held in the Imperial Garden.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55667] = { id = 55667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[55668] = { id = 55668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[55669] = { id = 55669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Radio Receiver TBD", description = "NYI - Will add Black Market viewing NPC in town" }
quests[55670] = { id = 55670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amathet Raiding Fleet" }
quests[55672] = { id = 55672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Historical Mess", description = "The text on this parchment appears to be Tortollan. Is it possible that Tortollans once resided on this island?  \n\nWe need to act quickly, before the creatures in this area destroy anymore evidence. Search the area for any signs of Tortollan relics.", progress = "Get to it, history is waiting for you!", completion = "Jolly good show. We'll be to the bottom of this mystery in no time!", objectives = "12 Tortollan Relics collected.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55681] = { id = 55681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Marks The Spot", description = "<This appears to be the remains of some kind of treasure map. However, the map is in poor condition after so many years of being subjected to the ocean.\n\nAccording to the map, the treasure should be somewhere nearby; but it's impossible to tell what exact location is from the ruined map.>", objectives = "Locate the buried treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55683] = { id = 55683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Memories", description = "Have we met before? I'm sorry... but I don't remember your name.\n\nMy name is... Arylina... I think. My memory has been so foggy since the great explosion happened that sent us underwater.\n\nOh! But look! I can see the sun and the stars again... I wonder what happened?\n\nI used to keep a diary, but I can't find it anywhere. If I just had my diary back, I'm sure I could remember more.\n\nWill you help me find it?", progress = "Where did I put that diary?", completion = "Oh... I remember now. This all happened so long ago. I think it's time for me to rest...", objectives = "Locate Arylina's diary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55685] = { id = 55685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Come in Peace... and Profit", description = "King Mechagon won't be happy we're on his island.\n\nBut a cruel king like that is gonna have enemies. You and I know that better than most, yeah?\n\nWhile Skaggit and the crew get our foothold dug in here, you and I are gonna find some potential allies to shield us from King Mechagon's wrath.\n\nThose two guards ran into that junkheap town up the hill. That place don't smell of royalty to me... Let's check there first.", progress = "Mechagon is not like the legends you were told.", completion = "Welcome to the Rustbolt Resistance.", objectives = "Explore the nearby town with Gazlowe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55686] = { id = 55686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrade Your Jetpack (Optional)" }
quests[55687] = { id = 55687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition GG-118 Micro-Jetpack" }
quests[55688] = { id = 55688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Growing Mystery", description = "This runestone could be of Vrykul origins. Is it possible that Vrykul once visited this island? \n\nWhere there's one runestone, there's usually more. The roots of lashers are drawn to the magic of runestones. If there are more buried here, the Lasher roots maybe wrapped around them!\n\nClear these lashers and see if any have runestones tangled in their roots.", progress = "Get to it, history is waiting for you!", completion = "Very good, We will examine these and see where it leads us.", objectives = "10 Ancient Runestones collected.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55694] = { id = 55694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Something in the Water", description = "The Ankoan must contend with threats from not only the naga, but also the horrors of N'Zoth. We learned early that if we allow his infection even the smallest purchase, he will grow and corrupt everything.\n\nThere is a great evil who is lingering near the waterway that flows through this place. It must be dealt with.", completion = "Another will take it's place, eventually. Like clearing weeds from a garden, it's a constant battle against invasion.", objectives = "Kill the Eye of the Corruptor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55695] = { id = 55695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That New Mount Smell", description = "Once every week, Mechagon expels a lot of excess oils through the outflow. That's why the place is a toxic mess!\n\nToday they expelled a batch of Golden Cogpaste. The stuff is amazing! I make air fresheners out of it. Makes any mount smell like it's brand new!\n\nCheck all the pipes in the outflow, and see if you can collect some of this paste.", progress = "I still could use that cogpaste.", completion = "I was running low on Air Fresheners, this will let me whip up a new batch right away!", objectives = "Collect 8 Golden Cogpaste.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55696] = { id = 55696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Drive", description = "There's still a lot of work to do, but it's running! We need to give the engine, brakes and gyro-balance actuator a good test. \n\nYou want to take it out for a drive and see how well they work?", progress = "Take it for a drive!", completion = "I was afraid you may not make it back!", objectives = "Drive it to the check point, reach Maximum speed, and test the emergency brake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55697] = { id = 55697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Leg Work", description = "The legs and shocks on this mount are shot! We'll need some new ones if we're going to get this mount crawling.\n \nA few weeks ago, Bondo and his gang rode into the Scrapbone Den hoping to scare the Troggs off. The Troggs tore their crawlers apart! The parts for those crawlers are still laying all around Scrapbone Den.\n\nSee if you can get us some of those parts from the Troggs.", progress = "We need those legs.", completion = "These parts will get us closer to being able to ride this thing!", objectives = "Collect 4 Mechaspider Leg and 12 Toe Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55701] = { id = 55701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snapdragon Claws", description = "Snapdragons are savage creatures that hunt in packs. Their presence in Nazjatar requires us to stay vigilant at all times.\n\nThey are crafty beasts, preferring to ambush their prey when it is weak or wounded. We will need to reduce the number of snapdragons in the area.\n\nThe last thing we need after a battle with the naga is to be finished off by a pack of blood-thirsty snapdragons!\n\nHunt down any nearby snapdragons and bring me a claw from each kill so that I may keep track of their numbers.", progress = "The snapdragon threat cannot be underestimated.", completion = "Good work, {name}. The fewer snapdragons in Nazjatar, the better.", objectives = "Collect 10 Snapdragon Claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55707] = { id = 55707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First One's Free", description = "The pocket-sized computational device can accept punch cards to upgrade and modify its performance.\n\nI could give you a punch card, but a particularly crafty trogg, Moch'k Eight-Thumbs, stole my satchel full of cards. \n\nKill Moch'k Eight-Thumbs, recover my satchel, and I'll set you up with a punch card for free.", progress = "Get that satchel back!", completion = "You are rather amazing for someone with so little mechanization!", objectives = "Punchcard Satchel recovered.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55708] = { id = 55708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgraded", description = "Well, look at you, {race}...\n\n<Christy's mechanical eyes quickly scan your body.>\n\nNot as impressive as I had hoped.\n\nKing Mechagon's armies are fully mechanized. But, you... you have a severe excess of flesh and matching machinery deficiency.\n\nYes, we simply must make a few changes... Maybe a neural-cranial upgrade!\n\nBring me a few microcogs from the motospiders nearby and I'll fix you up!", progress = "You must be able to out-think King Mechagon in battle. Get me those parts.", completion = "Your first upgrade! Try it out some before we attach it permanently.", objectives = "Collect 20 Microcogs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55712] = { id = 55712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrade Your A.T.O.M.I.K. Mk. II (Optional)" }
quests[55713] = { id = 55713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition A.T.O.M.I.K. Mk. II" }
quests[55714] = { id = 55714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind.\n\nMagical reinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", progress = "<The chest is locked and requires a key.>", completion = "<The magical barrier dissipates as you insert the key.>", objectives = "Locate the key to the Void Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55715] = { id = 55715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed Them All", description = "When we're doing our job right, we always have more mouths to feed!\n\nIf you could help with my stock, we could care for even more.\n\nBig, strong friends are what this revolution needs!", progress = "Do we have enough protein?", completion = "What a great help you are! I may grow to like you land creatures.", objectives = "Collect 10 Fathom Flesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55717] = { id = 55717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Heroics", description = "That card you found was a gold rare Huolon! \n\nI think that card belonged to Adalin Halfheight, one of our junior explorer league members.  If he dropped it, he and our other junior members maybe in trouble!\n\nWe need to find Leona Mistcaller, Dunkin Crackjaw, and Adalin Halfheight immediately!", progress = "Let's find these people!", completion = "You certainly are the hero they all talk about!", objectives = "Leona Mistcaller, Dunkin Crackjaw, and Adalin Halfheight rescued.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55718] = { id = 55718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Discovery", description = "<A very old ring of Nightelf origin. Seems out of place on this island, perhaps Elise Starseeker will know what to make of it>", completion = "This creates more questions than answers about this islands past.\n\nI'll look into this further when I return to Ironforge.", objectives = "Deliver the ring to Elise Starseeker.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55719] = { id = 55719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: A Few Starfish", description = "Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements.\n\nIf you happen upon any Angel Scale Starfish, please deliver them to the quartermaster as soon as possible.", completion = "Thank you for your contribution.", objectives = "Collect 3 Angel Scale Starfish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55720] = { id = 55720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: A Few Seaweed", description = "We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed, please give it to the quartermaster.", completion = "Thank you for your contribution.", objectives = "Collect 3 Sticky Seaweed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55721] = { id = 55721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: A Few Kelp Buds", description = "We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations.\n\nIf you happen to find any around Nazjatar, please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", completion = "Thank you for your contribution.", objectives = "Collect 3 Fallen Kelp Buds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55723] = { id = 55723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: A Few Carp", description = "Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!", completion = "Thank you for your contribution.", objectives = "Return 3 Struggling Carps to water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55724] = { id = 55724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: A Few Deepcoral Buds", description = "Many species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar.\n\nIf you could gather more deepcoral buds and return them to the quartermaster, you will surely be rewarded.", completion = "Thank you for your contribution.", objectives = "Collect 3 Deepcoral Buds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55725] = { id = 55725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: A Few Spiral Leaf", description = "We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster.\n\nI should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.", completion = "Thank you for your contribution.", objectives = "Collect 3 Poisonous Spiral Leaf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55726] = { id = 55726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: A Few Cone Shells", description = "If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support.\n\nIf you find yourself carrying Impregnable Cone Shells, please leave your stores with the quartermaster.", completion = "Thank you for your contribution.", objectives = "Collect 3 Impregnable Cone Shell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55727] = { id = 55727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: A Few Flotsam", description = "I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded.\n\nOnce you've gathered some supplies, return to the quartermaster for your reward.", completion = "Thank you for your contribution.", objectives = "Collect 3 Piles of Flotsam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55728] = { id = 55728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforced Cache", description = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a heavy-duty lock of some kind.\n\nReinforcement aside, the cache still requires a key to unlock.\n\nThe key is most likely being held by one of the nearby naga soldiers.>", progress = "<The chest is locked and requires a key.>", completion = "<As you turn the key you can hear the heavy latches of the chest snap open with considerable force.>", objectives = "Locate the key to the Reinforced Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55729] = { id = 55729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Resistance Needs YOU!", description = "Rustbolt isn't usually in this level of malfunction.\n\nKing Mechagon attacked our town last night. His mechanical armies captured many members of the Rustbolt Resistance and destroyed as much as they could before we drove them out.\n\nThe prisoners are being processed at Junkwatt Depot. After that, they'll be transferred down into King Mechagon's underground city... for full mechanization.\n\nWe can't let that happen. Will you help me rescue them?", completion = "This is where they process all prisoners before sending them into King Mechagon's city for reprogramming.", objectives = "Ride with Prince Erazmin to Junkwatt Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55730] = { id = 55730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing the Resistance", description = "King Mechagon is ruthlessly efficient. He only expends resources to kidnap those he deems worthy.\n\nThe rest, he... discards.\n\n<Prince Erazmin grimaces.>\n\nWe will deal with my father, King Mechagon, another day.\n\nThis information is more immediately relevant in that my father's predictability means our top scientists, engineers, and tinkerers should all be trapped, alive, somewhere in this depot.\n\nWe will find them, and break them out.", progress = "My father is short-sighted. He judges the worthiness of an individual in its current state. He fails to truly see their potential.", completion = "My father is short-sighted. He judges the worthiness of an individual in its current state. He fails to truly see their potential.", objectives = "Rescue the Rustbolt Resistance members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55731] = { id = 55731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Father's Armies", description = "My father was once a good leader. He envisioned a brighter future for his people, and did everything in his power to help us acquire it.\n\nBut when his vision became misaligned with the dreams of his people, he failed to adapt. Instead, he grew rigid, forcing his will on others.\n\nIn secret experiments, he began fully mechanizing the bodies of those who resisted him.\n\nIt was horrible to watch... there was nothing left of the original gnomes who followed him willingly.\n\nOnly robots remained. Slaves.", progress = "If we don't stop my father here, we will all share these poor gnomes' fates.", completion = "If we don't stop my father, we will all share these poor gnomes' fates.", objectives = "Kill 12 Mechagon forces in Junkwatt Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55732] = { id = 55732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Scar", description = "We've got a new problem, champion. Another grievous wound has opened up, this time at the Maelstrom!\n\nThe shaman there are in deep trouble, an' they need our help!\n\nSpeak tae MOTHER. She'll get ye tae the Maelstrom. I'll meet ye there.", completion = "I expected things tae be bad, but it's even worse than I thought!", objectives = "Speak to MOTHER to travel to the Maelstrom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55734] = { id = 55734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drill Rig Construction", description = "<Prince Erazmin sifts through the resources you both collected.>\n\nYes... This appears to be sufficient material to repair that drill rig.\n\nI'll do what I can with the parts that I have, but you will need to complete the repairs with yours.\n\nWhen you're ready, return to that broken drill rig we found and open it up.\n\nTogether, we'll have it up and running in no time.", progress = "You didn't lose your parts did you?", completion = "Keep an eye out for other construction projects across the island.\n\nThere's always something to build in Mechagon.", objectives = "Contribute Spare Parts and Energy Cells to the Broken Drill Rig construction project.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55735] = { id = 55735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Maelstrom", description = "The shaman of the Earthen Ring are powerful, but this is more than even they can handle! And from the sound o' it, some o' their own are still trapped down below.\n\nLike ye did in Nordrassil, use yer Heart of Azeroth tae seal up the wounds inflicted here. An' lay any crazed elementals tae rest before they make even more o' a mess.", progress = "This just keeps gettin' worse. If too many of these wounds open up, we may not be able tae heal the damage.", completion = "That was close! If ye hadn't stopped the spread of these wounds in time, I don't know what might've happened!", objectives = "Defeat Azerite elementals and seal Azeroth's injuries at the Maelstrom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55736] = { id = 55736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to the Resistance", description = "Life in the Rustbolt Resistance is not easy, {name}.\n\nBut it is yours. We will not order you around or force you to fight. Mechagon is a land of endless opportunities, and you may chase whichever opportunities you see fit.\n\nOf course, if you'd like suggestions for which improvements you most require, myself or any of the other mechagnomes in town will be happy to advise you of your current weaknesses.\n\nBut, for now, I ask simply that you walk with me to my workshop.", completion = "I wonder, what will you choose to do next?", objectives = "Tour Rustbolt with Prince Erazmin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55737] = { id = 55737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At the Azerite Time", description = "Ye did it! Ye stopped the damage before it could get any worse!\n\nThe Maelstrom will always be a place o' great history an' pain fer Azeroth, but any little bit we do will make things better. Who knows, maybe we can even heal Silithus one day!\n\nI'll meet ye back in the Chamber o' Heart. MOTHER's sure tae be interested in what happened here.", completion = "Heart examination complete. Additional Azerite amplification activated.", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55739] = { id = 55739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Chamber", description = "The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference.\n\nMake yer way tae the Chamber o' Heart, champion. Yer talents are needed.", completion = "The Heart o' Azeroth never ceases tae amaze me. Well done, champion!", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55742] = { id = 55742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bundle of Corroded Parts" }
quests[55743] = { id = 55743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Recycling", description = "<Recycling is fun and profitable. The Recyclerizer DX-82 stands ready to receive more scrap metal.>", progress = "<WARNING 3.6.4 - Y: Keep all appendages clear of doors or risk irreversible limb recyclerization.>", completion = "You deposit the bundle of parts into the Recyclerizer DX-82.  The doors close and the machine surges to life, a slight buzzing sound begins emanating from within. The sound increases in frequency, the slight buzz giving way to a high-pitched whirring. The machine shakes violently, seemingly ready to explode...", objectives = "Collect 1 Bundle of Recyclable Parts", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55750] = { id = 55750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Lady Naz'jess", description = "Wanted for attacks against the Alliance!\n\nLady Naz'jess is responsible for leading several raids and ambushes against our soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", progress = "Have anything to report?", completion = "Well done, {class}. Lady Naz'jess was a formidable foe and a high-ranking commander among the naga.", objectives = "Retrieve the head of Lady Naz'jess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55751] = { id = 55751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Water", description = "You see a lot up here. \n\nEven the water is a slave to the will of the naga.\n\nI believe we can help them reform away from here.\n\nBring back what you can!", progress = "Did you free them?", completion = "Well done, {race}!\n\nWe will hope for the best!", objectives = "Collect 15 Living Droplets from water elementals in Azsh'ari Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55752] = { id = 55752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Stand United", description = "The work ye've done tae empower the Heart o' Azeroth cannae be understated! With this power, we might just stand a chance o' savin' the world.\n\nIt's been a long fight fer certain, an' there is still more tae do. But fer now, we've got a little gift fer ye!\n\nLet me know when yer ready, champion.", progress = "Ain' it incredible, champion? There's no tellin' how powerful the Heart may yet become!", completion = "Amazin' isn't it? Tae see the dragonflights united in support o' Azeroth. Some o' them may be battered an' bruised, but they're still fightin'.\n\nBear their gifts well, Champion of Azeroth.", objectives = "Speak to Magni.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55753] = { id = 55753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knock His Bot Off", description = "I need to rebuild the main powercore. It's a 500S Mekronic so I'll need the operational schematics to get the work done. Only person I know who has a copy of that is Bondo Bigblock.\n\nWe're going to need Bondo's help to finish this. Maybe if you ask him, he'll lend us his schematics.", progress = "Did you make a deal with Bondo?", completion = "Great work {name}. All that's left is to rebuild this power core.", objectives = "Acquire the powercore schematics from Bondo Bigblock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55763] = { id = 55763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rescue of Meredy Huntswell", description = "Our expedition's mage, Meredy Huntswell, is being held by the harpies!\n\nWe've got to stop their ritual and rescue Meredy.\n\nYou lead the charge. Kee-La and I will back you up if things look dire.", completion = "Ye rescued me from a grim fate! Bein' a practicin' mage, I always figured one of me own spells would do me in, not a harpy!", objectives = "Rescue Meredy Huntswell from the harpy's necromantic ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55764] = { id = 55764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpy Culling", description = "The harpies are preparing for a dreadful assault, {name}. \n\nThey plan to attack our allies back at camp! \n\nHarpies swoop in and snatch their victims before bringing them back to their nests... to feast.\n\nWe have to stop them. Slay the harpies and their worgs to ensure their forces are too weak to stage an assault.", progress = "We must do what we can to fight the harpy menace. Take them down, as well as their worgs.", completion = "That should keep our camp safe for now. We must hurry and stop whatever these ogres have planned.", objectives = "Defeat 10 harpies and their allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55765] = { id = 55765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bugs, Lots of 'Em!", description = "You got a problem with mechanical bugs, so the Roughriders are here to sort this mess out!\n\nIn my experience, this big of an outbreak must have some sort of queen bug behind it all. We gonna go in, kill a lot of bugs till we find the leader of 'em all.\n\nHorde or Alliance don't matter, you're with the Roughriders today. Let's kill some bugs!", progress = "Do your job!", completion = "You took the battle to them. You are a Roughrider!", objectives = "Exterminate 20 motospiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55766] = { id = 55766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Sells These Shells", description = "Suva is so proud of her seashells. \n\nAfter everything she has done for our people, helping her supplies is the least we can do!\n\nHead down the hill and pick up some of the shiniest seashells you can find!\n\nYou will make her day.", progress = "<Excited clicks and squeaks.>", completion = "<Suva's feelers are twitching joyfully.>", objectives = "Collect 8 seashells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55767] = { id = 55767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misdirection", description = "We came in friendship and those pesky murlocs jumped us and stole my treasure.\n\nThey threw it in one of those big clams and ran off into the village.\n\nThey keep moving them around and I have no idea where it is now!\n\nCan you please help?", progress = "Any luck?", completion = "That's it! Dexter was so sad!\n\nThey thought they were so clever.\n\nNext time they're getting a kick to the dorsal fin.", objectives = "Find Dani's Treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55768] = { id = 55768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergent Sea Weeds", description = "There is a special kind of kelp that only grows near the vents.\n\nOur healers use these to help treat our friends in Newhome.\n\nMy kind don't have much of a chance down there, but you do!\n\nGather up some of the vent kelp sprouts in the Dragon's Teeth Basin and bring them to Nevin.", progress = "Were you able to find the special vent kelp?", completion = "These are perfect! \n\nA little kelp goes a long way!", objectives = "Gather 10 vent kelp sprouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55770] = { id = 55770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Commander Sarj'eth", description = "Wanted for attacks against the Alliance!\n\nCommander Sarj'eth is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", progress = "Have anything to report?", completion = "Well done, {class}. Sarj'eth was a formidable foe and a high-ranking commander among the naga.", objectives = "Retrieve the head of Commander Sarj'eth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55771] = { id = 55771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Lord Ha'kass", description = "Wanted for attacks against the Alliance!\n\nLord Ha'kass is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", progress = "Have anything to report?", completion = "Well done, {class}. Lord Ha'kass was a formidable foe and a high-ranking commander among the naga.", objectives = "Retrieve the head of Lord Ha'kass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55772] = { id = 55772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Lady Narjiss", description = "Wanted for attacks against the Alliance!\n\nLady Narjiss is responsible for leading several raids and ambushes against our soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", progress = "Have anything to report?", completion = "Well done, {class}. Lady Narjiss was a formidable foe and a high-ranking commander among the naga.", objectives = "Retrieve the head of Lady Narjiss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55773] = { id = 55773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Gler'thogg", description = "Wanted for attacks against the Alliance!\n\nGler'thogg is responsible for the gruesome deaths of several of our best soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", progress = "Have anything to report?", completion = "Well done, {class}. Gler'thogg was a formidable foe and a high-ranking commander among the naga.", objectives = "Retrieve the Eye of Gler'thogg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55774] = { id = 55774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Inquisitor Ithriza", description = "Wanted for attacks against the Alliance!\n\nInquisitor Ithriza is responsible for leading several raids and ambushes against our soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", progress = "Have anything to report?", completion = "Well done, {class}. Inquisitor Ithriza was a formidable foe and a high-ranking commander among the naga.", objectives = "Retrieve the head of Inquisitor Ithriza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55775] = { id = 55775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Haggronar", description = "Wanted for attacks against the Alliance!\n\nHaggronar is responsible for the gruesome deaths of several of our finest soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", progress = "Have anything to report?", completion = "Well done, {class}. Haggronar has been terrorizing our soldiers since the day we arrived on Nazjatar.", objectives = "Retrieve the head of Haggronar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55776] = { id = 55776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Emorneth", description = "Wanted for attacks against the Alliance!\n\nEmorneth is responsible for the gruesome deaths of several of our best soldiers. Extreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", completion = "Well done, {class}. Emorneth has been terrorizing our soldiers since the day we arrived on Nazjatar.", objectives = "Slay Emorneth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55777] = { id = 55777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Braxicus", description = "Wanted for attacks against the Alliance!\n\nBraxicus is responsible for the gruesome deaths of several of our finest soldiers.\n\nLast seen near the vicinity of this command poster.\n\nExtreme caution advised!\n\nUpon completion of the mission, report to Lieutenant Hawkins for commendation.", progress = "Have anything to report?", completion = "Well done, {class}. Braxicus has been terrorizing our soldiers since the day we arrived on Nazjatar.", objectives = "Retrieve Braxicus' giant claw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55778] = { id = 55778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of Danger", description = "{name}, Spiritwalker Ussoh has revealed a disturbing vision to me regarding Baine Bloodhoof.\n\nHe has asked that you speak with him as soon as you can.\n\nReturn to me after. We will have much to discuss.", completion = "Sylvanas will execute Baine Bloodhoof soon... unless we act.", objectives = "Speak with Spiritwalker Ussoh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55779] = { id = 55779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stay of Execution", description = "Come. It is time to save a friend.", completion = "Thank the Sunwell you were able to save Baine's life, {name}. Thank you.\n\nAnd Jaina Proudmoore came to his aid as well. Interesting...", objectives = "Complete the \"Stay of Execution\" Scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55782] = { id = 55782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stay of Execution", description = "Baine's time is short. We must act now.", completion = "A pity Bloodhoof and all the rest survived.\n\nOur Warchief has anticipated this outcome, however.", objectives = "Complete the \"Stay of Execution\" Scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55783] = { id = 55783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stay of Execution", description = "When I was younger, Baine Bloodhoof and I began exchanging letters. Through our unlikely friendship, I learned that there was nobility in the Horde.\n\nHe proved that by defying Sylvanas when she planned to strip the free will from Derek Proudmoore. That act of nobility will cost him his life... unless we intervene.\n\nIf there is to be peace in Azeroth, our hope depends upon good people doing the right thing. People like Baine. People like you.\n\nPlease, go with Jaina. Save my friend and see him home.", completion = "Thank you for helping us rescue Baine.\n\nIt was the right thing to do.", objectives = "Complete the \"Stay of Execution\" Scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55784] = { id = 55784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Payment in Kind", description = "{name}, King Anduin has requested our presence in Stormwind.\n\nWe've sent him reports on our situation here in Nazjatar, and he understands the severity of the threat we're facing. For him to pull both of us back from the front lines, it must be a matter of grave importance.\n\nI will meet you in Stormwind Keep.", progress = "Thank you for coming, {name}.", completion = "We may be at war with the Horde, but that did not stop Baine from doing the right thing.\n\nWe can do no less for him.", objectives = "Meet with Anduin Wrynn in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55785] = { id = 55785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: More Starfish", description = "Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements.\n\nIf you happen upon any Angel Scale Starfish, please deliver them to the quartermaster as soon as possible.", completion = "Thank you for your contribution.", objectives = "Collect 5 Angel Scale Starfish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55786] = { id = 55786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: More Seaweed", description = "We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed, please give it to the quartermaster.", completion = "Thank you for your contribution.", objectives = "Collect 5 Sticky Seaweed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55787] = { id = 55787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: More Kelp Buds", description = "We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations.\n\nIf you happen to find any around Nazjatar, please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", completion = "Thank you for your contribution.", objectives = "Collect 5 Fallen Kelp Buds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55789] = { id = 55789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: More Carp", description = "Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!", completion = "Thank you for your contribution.", objectives = "Return 5 Struggling Carps to water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55790] = { id = 55790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: More Deepcoral Buds", description = "Many species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar.\n\nIf you could gather more deepcoral buds and return them to the quartermaster, you will surely be rewarded.", completion = "Thank you for your contribution.", objectives = "Collect 5 Deepcoral Buds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55791] = { id = 55791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: More Spiral Leaf", description = "We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster.\n\nI should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.", completion = "Thank you for your contribution.", objectives = "Collect 5 Poisonous Spiral Leaf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55792] = { id = 55792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: More Cone Shells", description = "If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support.\n\nIf you find yourself carrying Impregnable Cone Shells, please leave your stores with the quartermaster.", completion = "Thank you for your contribution.", objectives = "Collect 5 Impregnable Cone Shell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55793] = { id = 55793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: More Flotsam", description = "I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded.\n\nOnce you've gathered some supplies, return to the quartermaster for your reward.", completion = "Thank you for your contribution.", objectives = "Collect 5 Piles of Flotsam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55794] = { id = 55794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclamation Rig" }
quests[55795] = { id = 55795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mountain On the Move", description = "I have seen such fervor only once before.\n\nIn times of peril, Torcali may call upon her children to defend her and those she looks after.\n\nIt is likely she called your beast away. Go to her and see how you can help.", completion = "<Torcali's voice enters your mind.>\n\nI have called and you have come once again, {name}. We have little time to waste.", objectives = "Speak to Torcali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55796] = { id = 55796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heresy at the Crossroad", description = "<Torcali's voice enters your mind.>\n\nMy followers undertook a pilgrimage to a place called the Antul'Mita Plateau. It is regarded as the crossroads of Zandalar among my faithful and is the site of a Greater Wayshrine.\n\nI sense some great peril has fallen upon them.\n\nI have sent my children and my champion, Jo'nok, to their aid. Your charge is among them. Go to her and ensure that my acolytes reach the shrine safely.\n\nLet nothing stand in your way.", completion = "She is ready. You are ready. This one thinks dey have made a mistake in challenging us.", objectives = "Meet Jo'nok at the Antul'Mita Plateau in Nazmir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55797] = { id = 55797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Direhorn Mother's Fury", description = "This one protects de faithful who still seek de shrine.\n\nYou will take your companion and show them de fury of a mother direhorn.\n\nTrust in your young friend. She has always known how to fight.\n\nOpen de way. Slay de heretics that defile our loa's shrine.", progress = "A direhorn is gentle until it is provoked. Their mistake.", completion = "It is a joy to behold her strength, {name}. Our faith is rewarded.", objectives = "Clear a path to the Greater Wayshrine in the Antul'Mita Plateau.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55798] = { id = 55798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wander Not Alone", description = "She is here. I can feel her eyes upon us.\n\nMy loa is generous. She will reward you for de service you have given her.\n\nGreat Wanderer guide your path, {name}.", completion = "<Torcali's voice enters your mind.>\n\nTime and time again I have called upon you. Time and time again you have answered.\n\nThe little one tells me she will follow you wherever it is that you wish to go. After all that you have done for my faithful and my young, this is my gift to you.\n\nFrom this day until the end of your days, you will wander not alone.\n\n<Torcali gently touches her great snout to your head.>\n\nThank you and farewell, {name}.", objectives = "Speak to Torcali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55799] = { id = 55799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tide Turns", description = "The time to strike is now. We must take the Tidestone of Golganneth and the Javelin of Suramar is our best chance of piercing the barrier around it.\n\nEvery minute we wait is another minute when the sea can come crashing down on us. What forces we have will be arrayed below, just outside their encampment.\n\nWe will need your strength in addition to the Javelin, {name}. We do not have enough forces to take it on our own.", completion = "Quickly, the Tidestone!", objectives = "Assault the naga camp and seize control of the Tidestone of Golganneth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55801] = { id = 55801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition: We Need It All", description = "We are dangerously low on all of our supplies. Please, you must go out and collect as much as you can.\n\nPlease return with any resources you find to the quartermaster!", completion = "Thank you for your contribution.", objectives = "Collect resources from around Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55813] = { id = 55813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aim High", description = "This conspiracy of ravens is preying on citizens of Rustbolt, it's unacceptable! \n\nPrince Erazmin has asked me to reduce their numbers, but I could really use your help. Can you help me kill some of them? \n\nUse my marker gun if you need it. I'll blast the ones you mark, and help bring them down.", progress = "Let's get to it!", completion = "We make a superior team.", objectives = "12 Rustwing Ravens slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55815] = { id = 55815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Other Interests", description = "Madam Goya is interested in many unusual items other than just rare metals.\n\nKeep an eye out for these particular items during your travels in Nazjatar.\n\nDeliver them to me and Madam Goya will consider you for special access.", progress = "Have you found these items?", completion = "Excellent work, we shall speak again.", objectives = "Deliver 5 Particularly Dense Rock to Steelsage Gao.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55816] = { id = 55816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Other Place", description = "In my travels of the many possible futures, I discovered another place much like Rustbolt, but different.\n\nIn this other time and place, very little is alive, everything is machines.\n \nYou must travel to this other place. You will scan the memory banks of the Clockwork Giants you find there. Then we will use that data to ensure that our Rustbolt never becomes the other place.", progress = "You must accomplish this task, for all of our sakes.", completion = "With this perhaps we can alter the timeline that would bring us all to this place.", objectives = "Scan 10 Clockwork Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55818] = { id = 55818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: A Few Naga", description = "The naga are our true enemy. All other efforts in Nazjatar are second to disrupting the naga's operations. If you want to be an asset to our cause then destroying the enemy is a quick way to earn your way here.\n\nWhen you have completed your task, report to the quartermaster to claim your reward.", progress = "I know it is dirty work, but someone must do it.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 15 naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55819] = { id = 55819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: A Few Murlocs", description = "While murlocs are often only a nuisance, certain factions are becoming more of a danger to our people. It is time we work together to preserve our safety while moving about Nazjatar.\n\nPut an end to some of the more aggressive murlocs and the quartermaster will award you.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 15 murlocs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55820] = { id = 55820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: A Few Hydras", description = "Our forces are desperately outmatched when it comes to the hydras. They are ferocious, tenacious, and deadly. We have retreated almost entirely out of the western region of Nazjatar.\n\nIf we are going to hold the line against the naga, we need to make sure the western region is safe for our forces. Destroy as many hydras as you can manage, then report to the quartermaster.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 10 hydras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55821] = { id = 55821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: A Few Coral Ancients", description = "Coral ancients are beginning to awaken from their long slumber. I warn you, these are very dangerous creatures of immense size and power. If more of them begin to awaken, our forces will be in great danger.\n\nOnce you have defeated some of these ancients, report to the quartermaster to claim your reward.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 3 Coral Ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55822] = { id = 55822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: A Few Makrura", description = "The makrura have been a thorn in our side for too long. They are aggressive towards almost all species in Nazjatar and are very dangerous in groups. Less of them in our waters would certainly benefit our cause.\n\nOnce you are done, report to the quartermaster to claim your reward.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 10 makrura.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55823] = { id = 55823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: A Few Crabs", description = "The crab population is expanding too quickly within Nazjatar, endangering local plant life. Cull their numbers in our conservation effort.\n\nReport to the quartermaster to claim your reward.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 15 crabs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55824] = { id = 55824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: A Few Snapdragons", description = "Snapdragons are one of the most dangerous species on Nazjatar. The naga breed them for the viciousness and their ability as trackers.\n\nIf we hope to keep our positions hidden from the naga, we must take out these groups of snapdragons immediately.\n\nAfter you are done, report to the quartermaster to claim your reward.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 10 snapdragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55825] = { id = 55825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: A Few Fathom Rays", description = "The fathom ray population is eating all of the coral buds to the east. If we do not cull their numbers, we may have an environmental catastrophe on our hands.\n\nOnce you have finished, report to the quartermaster to claim your reward.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 10 fathom rays.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55827] = { id = 55827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: More Naga", description = "The naga are our true enemy. All other efforts in Nazjatar are second to disrupting the naga's operations. If you want to be an asset to our cause then destroying the enemy is a quick way to earn your way here.\n\nWhen you have completed your task, report to the quartermaster to claim your reward.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 25 naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
