quests[55836] = { id = 55836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: Elite Naga Forces", description = "Strike at the elite naga forces within Nazjatar. Once we remove some of their leadership, our people will be able to move about more freely.\n\nReport to the quartermaster to claim your reward.", progress = "I know it is dirty work, but someone must do it.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 5 elite naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55837] = { id = 55837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty: Dangerous Creatures", description = "There are creatures in Nazjatar that are far more dangerous than their peers. I leave it to you to find them and defeat them.\n\nWhen you've done your part, report to the quartermaster to claim your reward.", progress = "I know it is dirty work, but someone must do it.", completion = "This will ease our efforts in Nazjatar.", objectives = "Kill 1 rare creature in Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55845] = { id = 55845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plans of Attack", description = "<The attack plans are written on the parchment in fluorescent squid-ink and bound together with Azshara's seal.>\n\nOrders from our queen:\n\nQueen Azshara has commanded that all naga forces prepare for a full assault upon the Alliance invaders in our land. Details for the attack have been distributed to your various unit commanders.\n\nThe Alliance shall tremble at the might of our queen!", progress = "What news do you bring from the front?", completion = "Excellent work, {class}. You've done the Alliance a great service. With these plans in hand, we will be able to prepare our defenses in advance of the attack.", objectives = "Collect 8 Assault Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55846] = { id = 55846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Rituals", description = "The naga use dark, forbidden rituals to subjugate the elements to their will.\n\nBut such rituals threaten to destroy the elemental balance that binds this world together. The rituals must be stopped. \n\nFortunately, the rituals the naga use are too elaborate to commit to memory. The ritual instructions are contained within ancient texts.\n\nIf we destroy the ancient tomes that contain the rituals, the knowledge will be lost to the naga forever.\n\nRetrieve the tomes and I will see that they are destroyed", progress = "Do you have the tomes?", completion = "I will see to it that the tomes of binding are destroyed at once. May Neptulon guide your journey, {class}.", objectives = "Collect 8 Tomes of Binding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55849] = { id = 55849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclamation Rig" }
quests[55851] = { id = 55851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essential Empowerment", description = "Champion, excitin' news!\n\nI know yer busy dealin' with the naga threat right now, but we need ye to come back tae the Chamber of Heart! MOTHER's finally finished her calculations and she's got an idea of what tae do next!\n\nHurry back tae Silithus as quick as ye can. Azeroth needs ye!", progress = "There ye are! Chamber's lookin' better, eh?", completion = "Welcome back, champion! We've got loads tae do now that MOTHER's finished her calculatin'.\n\nLet's get started, eh?", objectives = "Meet Magni in the repaired Chamber of Heart in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55860] = { id = 55860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Slug Liquidation", description = "My brief studies have shown that the refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. \n\nThe sea floor is littered with creatures that produce just what we need to track down this weapons cache.", progress = "Do you have the ooze?", completion = "The substance is stickier than expected, but should still work.", objectives = "Collect 8 Bioluminescent Ooze from Luminescent Sea Slugs within Bloodfin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55861] = { id = 55861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Residue Lead You", description = "I have fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. \n\nIt should give you a clear trail to the weapons cache. \n\nGood luck, {name}.", completion = "<Although tightly sealed, the radiating energy and weight suggest that the crate contains Azerite weapons.>", objectives = "Follow the residue trail to locate the Azerite Weapons Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55862] = { id = 55862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insight into Our Enemies", description = "There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. \n\nAlthough our new allies have suffered greatly at the hands of the naga, their hardships will not be in vain. \n\nThe kelfin should have invaluable knowledge of Azshara's forces. \n\nWith their help, we might be able to learn more about how our enemies operate.\n\nSpeak with Neri and see what insight she can provide.", completion = "You want some insight into the naga?\n\nI can tell you what I know, but the kelfin who are still being held captive can give you a firsthand account.", objectives = "Speak to Neri to learn more about the naga within Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55863] = { id = 55863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deteriorating Knowledge", description = "The kelfin are no strangers to Azshara's cruelty. \n\nShe commands creatures of darkness that entrap my kind and warp their minds. They eat away at their memories until nothing's left but an empty husk. \n\nIf you can get to them soon, perhaps they'll still be in a state worth saving.", completion = "I thought I'd die in that cave. Sometimes, I wished it. \n\nThank you for getting me out of there, {name}.", objectives = "Rescue Fenn, Kono, and Esma from the clutches of mind-leeching Zoatroids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55864] = { id = 55864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price is Death", description = "We've long believed that the ocean is big enough for all that wish to call it home. \n\nUnfortunately, the naga don't see it that way. \n\nThey kill and capture our kind without remorse, and it's about time they paid the price.", completion = "If they're dead, they can't hurt me anymore. \n\nIf I keep telling myself that, soon enough I'll believe it, right?", objectives = "Kill 10 naga within Zanj'ir wash and the Deepsea Slave Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55865] = { id = 55865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Know of the Naga", description = "It feels good to be me again. I have you to thank for that.\n\nMy head still hurts from the zoatroid's influence, but I think the others are worse off.\n\nPut some of this salve on their wounds, and I'll do my best to tell you what I know about the naga.", progress = "You're interrupting.", completion = "Whatever is hidden within the stronghold needs to be destroyed.", objectives = "Tend to the Kelfin's wounds and hear what Fenn has to say about the naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55866] = { id = 55866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Undercover", description = "Entering the stronghold alone would be a death wish.\n\nThe Zanj'ir slaughter outsiders on sight. \n\nThe only way to get in without being killed is to appear to be under the effects of a zoatroid. \n\nEven then, the mind-shackled are put to work. \n\nYou must obey all commands, or they will know your mind is still your own. \n\nOnce the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.", completion = "What use are you to us if you're not working?", objectives = "Scout Zanj'ir Terrace while pretending to be mind-shackled.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55867] = { id = 55867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coveted Crystals", description = "Locating the weapons cache shouldn't be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all we need!\n\nIt all seems rather simple, doesn't it? But the key is in the Deepsea Crystal used to refract the light. \n\nI am told that the Bloodfin tribe covets these crystals, so it shouldn't be too much trouble to get your hands on one.", progress = "Have you found the crystal?", completion = "The clarity on this gem is rather remarkable, wouldn't you say? I think it'll do nicely.", objectives = "Collect a Deepsea Crystal from Hoarder Moarrgl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55868] = { id = 55868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let the Residue Lead You", description = "I've fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. \n\nIt should give you a clear trail to the weapons cache. \n\nGood luck, {name}.", completion = "<Although tightly sealed, the radiating energy and weight suggest that the crate contains Azerite weapons.>", objectives = "Follow the residue trail to locate the Azerite Weapons Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55869] = { id = 55869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing Out the Cache", description = "<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>", completion = "It seems Azshara's influence reaches even further than we thought. \n\nAshvane may have escaped, but at least we have secured the weapons.", objectives = "Deal with Priscilla Ashvane and her minions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55870] = { id = 55870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Slug Liquidation", description = "The Azerite refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. \n\nThe sea floor is littered with creatures that produce just what we need to track down this weapons cache.", progress = "Do you have the ooze?", completion = "It's stickier than expected, but should still work.", objectives = "Collect 8 Bioluminescent Ooze from Luminescent Sea Slugs within Bloodfin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55871] = { id = 55871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Friends", description = "Outside is dangerous.\n\nIt is safe in the Kelfin Pocket. \n\nWe find the lost crabs, and slugs, and other friends.\n\nHere they get a new name and a new home. \n\nFind friends like these, and bring them home.", progress = "Did you bring us friends?", completion = "They are already my friends. Now they are safe.\n\nThank you, {name}.", objectives = "Collect Sandclaw Crabs and Muck Creepers for Narm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55872] = { id = 55872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where They Hide", description = "Those sneaky snakes have started to send assassins.\n\nThey hide nearby and kill those they cannot take away to the slave pens.\n\nEven the sponges want to be rid of them! \n\nThe spores will reveal the naga treachery... and then you can go ahead and kill them. \n\nWe must keep our people safe!", progress = "Did you find them all?", completion = "Ha! They hate those things.\n\nNicely destroyed.", objectives = "Use the Fresh Sponge to reveal and kill 5 Zanj'ir Assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55873] = { id = 55873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Kritch", description = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. \n\n<Rlgmrr jumps around anxiously and points toward the cave.>\n\nGrrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr.\n\n<He makes a scary face and pinching motions with his hands.>\n\nMrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", progress = "Mrgglrmr grm?", completion = "Llrmmrgl! Mrgggl mrgl!\n\n<Rlgmrr laughs.>", objectives = "Kill the Kritch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55874] = { id = 55874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "We're getting a geyser hit any minute now.\n\nThe effects of the Tidestone are far-reaching.\n\nWe have to do what we can to prevent any further destruction.\n\nUse this sealant to stall off the next round of eruptions!", progress = "Did you take care of all of them?", completion = "Did it get you once? I feel like it got you.\n\nHappens to the best of us! Great work.", objectives = "Seal all of the unstable geysers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55875] = { id = 55875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "Just keep watching this spot... any second now...\n\nOnce those geysers start firing, get in there and seal them up.\n\nThe more they shake, the more everything breaks apart!\n\nWe have to keep these things under control.", progress = "Is it all sealed up?", completion = "Good work!\n\nI was hoping for a little help from the Reefwalkers, but we take what we can get!", objectives = "Seal all of the unstable geysers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55876] = { id = 55876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "Earthquakes! Snakes! Water coming from every direction.\n\nWhat is going on around here?\n\nNeri said to plug some holes in the defenses - didn't think she'd mean it literally.\n\nTake some of this goo, next eruption, stick it in the hole.", progress = "Goop them all up?", completion = "Yeah! That was some surftastic heroing!", objectives = "Seal all of the unstable geysers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55877] = { id = 55877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "We have been keeping an eye out for these unstable geysers.\n\nSince the water went away, the ocean has been trying to find a way back in.\n\nIf we let it burst up just anywhere, we could all be doomed!\n\nHelp me plug these up!\n\nBe careful, though, I found out the hard way they have a bit of a kick.", progress = "Did you prevent the disaster?", completion = "The ocean's own luck was with us! Well done, {race}.", objectives = "Seal all of the unstable geysers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55878] = { id = 55878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Geysers", description = "Have you heard about the geysers? \n\nAll over the newly exposed areas, water trying to fill where it was pulled away.\n\nThe ocean, she is angry. I don't think she likes Azshara either.\n\nWe will keep filling this in until we can find a permanent fix.", progress = "Get them stopped up for now?", completion = "Thank you, friend.\n\nI have a feeling that won't hold for long.", objectives = "Seal all of the unstable geysers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55879] = { id = 55879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride of the Scientifically Enhanced Boar", description = "We don't know how long the re-sizing will last, so let's get moving.\n\nYou're going to ride this giant boar and mow down the army of undead between us and Wrathion.\n\nThe large ones are pulsing with shadow magic. If you kill them, I bet it they'll take out any enemies near them.\n\nLet's hope Wrathion is willing to help us find Kalecgos.", progress = "Please... help! I won't last much longer!", completion = "Thank you, stranger. I thought I was going to be punished for failing to save my friends.\n\nI'm relieved that I was mistaken.", objectives = "Ride the Giant Boar to destroy the undead army.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55880] = { id = 55880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redistribution of Power", description = "Welcome back, dear test subject.\n\nToday's experiment is...\n\n<Pristy flips through some papers and smiles.>\n\n...My pet project, the NRG-100!\n\nI am quite pleased with the potential improvements I've made to efficiency, potency, and destructivity.\n\nAnd the only thing I had to sacrifice was stability!\n\nWhen you're ready to proceed, strap on the NRG-100.", progress = "Let's experiment!", completion = "Wondrous experimentation, dear test subject!\n\nI'll make further modifications to the NRG-100 based on these results. It will be ready for our follow-up test in a few days.", objectives = "Use the NRG-100 to charge 6 energy cells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55881] = { id = 55881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purge the Totems", description = "The harpies' totems are scattered throughout the area.\n\nHarpies are known for using their magic to corrupt those nearby. Even now, I can hear foul whispers in the air...\n\nWe must destroy these totems before any of us are tainted by their dark magic!", progress = "The totems are not particularly powerful. A simple light and tinder should do.", completion = "The foul magic in this area is dissipating. I think we're safe for now.", objectives = "Set fire to 5 Harpy Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55882] = { id = 55882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to Base", description = "We did it! We're one step closer to getting off this island.\n\nLet's get back to camp and inform the captain of our success.", completion = "I'm relieved you rescued Meredy. That's one more life saved and one fewer sacrificed.\n\nAnd I'm glad to see you helped Henry get back to his old self.\n\nWe'll work with Meredy to figure out a plan of action.", objectives = "Return to the Alliance Camp and speak with Captain Garrick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55883] = { id = 55883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Soar Like a Ray", description = "I like to find the eggs of the fathom rays before they hatch so we can form a bond with them.\n\nAt least, when we can't swim, we can fly!\n\nBring me a few more eggs to start a new thing - we'll call them Rayriders!", progress = "Did you find many eggs?", completion = "Ah! Perfect! Soon we will feel the wind!", objectives = "Bring back 7 fathom ray eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55884] = { id = 55884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infestation of Madness" }
quests[55885] = { id = 55885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rico's Rescue", description = "Some of our Roughriders are missing, I tried to find them, but got pinned down here by the bugs! \n\nI could really use your help, {name}. See if you can save my missing troopers.", completion = "Rico put in a good word for you. Could mean a promotion sometime.", objectives = "Rescue Trooper Levy, Katrin, and Bybee.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55886] = { id = 55886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zanj'ir Brutalizer" }
quests[55887] = { id = 55887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Alzana, Arrow of Thunder" }
quests[55888] = { id = 55888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Qalina, Spear of Ice" }
quests[55889] = { id = 55889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Kyx'zhul the Deepspeaker" }
quests[55890] = { id = 55890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Vyz'olgo the Mind-Taker" }
quests[55891] = { id = 55891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Aldrantiss, Defender of Her Kingdom" }
quests[55892] = { id = 55892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion Eldanar, Shield of Her Glory" }
