quests[55900] = { id = 55900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kassar, Wielder of Dark Blades" }
quests[55901] = { id = 55901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Rebellion", description = "Aid the Rustbolt resistance." }
quests[55905] = { id = 55905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abduction Reduction", description = "We got actual ABDUCTIONS happenin' here, {name}!\n\nHonest to gold, flying robots are swoopin' into town and snatchin' up people like it's closin' time at Gallywix's buffet!\n\nLucky for the Rustbolt Resistance, Gazlowe called in me and my explosives to save the day.\n\nYou wanna pitch in? Take one of my rocket launchers and blast those containment crates outta the sky.\n\nWhatever they've got trapped inside will come tumblin' down real fast, so you gotta run underneath and catch 'em.", completion = "Nice shootin' out there!\n\nAnd, hey, don't worry if you \"accidentally\" missed a Mechagnome or two... I did too!\n\n<Penny winks at you.>", objectives = "Free 6 captured Mechagnomes and catch them before they hit the ground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55937] = { id = 55937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing Out the Cache", description = "<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>", completion = "It seems Azshara's influence reaches even further than we thought. \n\nAshvane may have escaped, but at least we have secured the weapons.", objectives = "Deal with Priscilla Ashvane and her minions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55965] = { id = 55965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westward Bound", description = "Captain Garrick wants us tae search west o' camp fer any other members of the expedition.\n\nAlaria and I will go on ahead. Meet us tae the west and we'll see what we can find.", completion = "A giant pit of spiders right on our doorstep! Aren't we the lucky ones?", objectives = "Meet Bjorn Stouthands west of the Alliance Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55967] = { id = 55967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sating Snapdragons", description = "It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. \n\nThe beasts will eat anything, including your arm if you don't move it away quickly enough. \n\nLuckily for you, they've developed a taste for Chitterspine Roe.", completion = "I'm surprised they didn't make a meal out of you.", objectives = "Collect Chitterspine Roe and feed it to Savage Snapdragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55970] = { id = 55970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attrition" }
quests[55973] = { id = 55973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepcoil Experiments" }
quests[55976] = { id = 55976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Waveblade Ankoan", description = "The Waveblade Ankoan appreciate all the aid you've provided.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", completion = "Thanks to your efforts against the naga, our clan has been able to secure additional resources from the battlefield.  Please accept this gift of supplies, {name}. \n\nThe more you continue to dominate the battlefield the more resources we can spare.", objectives = "Speak with Speaker Utia in Mezzamere for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55979] = { id = 55979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iteration is Key", description = "You've been holding out on me!\n\nHere I was, thinking that we're friends now and yet you neglected to tell me about your magnificient wrench!\n\n<Christy inspects it closely.>\n\nWell, not too magnificient... I recognize the Ub3r-Spanner from its blueprints, but whoever built this lacks a certain level of craftsmanship.\n\nI will upgrade it for you. Bring me the Overcharged Mecha-core from a mechanocrawler.\n\nNo excuses. I will fix your mistakes.", progress = "Imagine crafting an Ub3r-Spanner without an overcharged mecha-core... Ha!", completion = "This will only take a minute. Keep a close eye on what I do, and you will learn a thing or ten.", objectives = "Collect an Overcharged Mecha-core from the Overcharged Mechanocrawler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55980] = { id = 55980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn the Scale", description = "I have been trying to gather some of the scales from the young hydra nearby. \n\nTheir flexibility and strength makes them incredibly versatile.\n\nWith all the cranky old hydra tromping around, I don't stand much of a chance. \n\nCan you gather some up for me?", progress = "Do you have enough?", completion = "You aren't as slow as I thought you'd be, with those land foots.", objectives = "Collect 20 Hydra Scales from nearby hydra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55981] = { id = 55981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Beneath Their Eyes", description = "We need to get inside Darkmaul Citadel, rescue the captain of the expedition, and stop the ogre behind all of this.\n\nMeredy is going to cast an illusion to make you look like an ogre, and you're going to take us all in as \"prisoners.\"\n\nI'll be hiding my efforts to suppress the shadow magic in the meantime.\n\nSpeak with Meredy when you're ready for her to cast the spell.\n\nHer illusion spell should be temporary, as long as she casts it in the proper way.", completion = "We're close to stopping all of this. We just need to push a little further.", objectives = "Have Meredy transform you into an ogre, then scout the nearby ogre citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55982] = { id = 55982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lords of Water" }
quests[55983] = { id = 55983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Safer Place", description = "<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Mezzamere.>", completion = "<Mrrl seems at home in his new spot and his family has also taken up refuge here. It is unlikely you will be able to remove this new murloc infestation.>", objectives = "Escort Mrrl back to Mezzamere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55984] = { id = 55984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Offense", description = "Korl was told to watch the naga, so watching the naga I am.\n\nThey're bad, friend, you know... just... terrible, horrible, bad monsters. \n\nI don't think I can just watch any more.\n\nThey say the best defense is.. something...\n\nHelp me teach them being being bad gets you smashed!", progress = "Did you have fun?", completion = "This was my best day. Thank you, friend.", objectives = "Kill 50 naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55985] = { id = 55985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extra Shiny", description = "In the pools below are some small, lovely pearls. \n\nThey were tossed in during some Azsh'ari ritual. \n\nDo they mean something? I have no idea. But I would like to have some of them. \n\nBe a lovely heavyfoot and go grab some for me, please!", progress = "Did you find all of the pearls?", completion = "I can feel them glowing! They tingle through my hand and into the ocean floor.\n\nVery lovely.", objectives = "Collect 10 Imbued Pearls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55986] = { id = 55986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break a Few Eggs", description = "This chamber is lovely and terrifying. \n\nWhat is born here will ruin the lives of so many. \n\nWe cannot hurt the pods, but we can destroy the eggs of the serpents that guard them.\n\nTake out the eggs, every little bit helps.\n\nPoor eggs...", progress = "Did you destroy the eggs?", completion = "The fewer creepy flying snakes we have guarding the naga, the better.", objectives = "Destroy 10 Deepcoil Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55988] = { id = 55988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Ogres to the Slaughter", description = "This is bad, {name}. Captain Kelra is bound by magic, the ogres are preparing to attack our friends, and the ritual is almost complete!\n\nI have to stay calm. We can't give up now, right?\n\nThis may sound risky, but we need to take the fight to the ogres.\n\nWe're behind enemy lines, so we'll be able to get the jump on them and draw their focus away from the camp.\n\nTake down any ogres that you can. That should keep them away from our friends.", progress = "You need to slay the ogres so they don't go after our friends back at the camp.", completion = "This should buy us enough time to stop the ritual!", objectives = "Slay 8 ogres within Darkmaul Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55989] = { id = 55989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catapult Destruction", description = "Did you notice the catapults on our way up? It appears the ogres plan to attack our allies below.\n\nLindie anticipated something like this and provided several bombs to handle siege weapons.\n\nJust don't shake them too hard.", progress = "Don't worry about the bombs. They'll blow up those catapults just fine.", completion = "Great work! I'll have tae tell Lindie that his bombs worked perfectly.", objectives = "Blow up 4 catapults within Darkmaul Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55990] = { id = 55990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Controlling their Stones", description = "Captain Kelra won't last much longer. We need to acquire the ward stones to break the ritual before it kills her.\n\nI'll continue weakening the main ritual. Get those ward stones from the ogre lieutenants nearby.", progress = "So, these were the stones used to bind me? The ogres clearly were concerned about you thwarting their plans.", completion = "Thank you for saving me, but we have no time to lose. The ogres will not stop until they have raised the dragon!", objectives = "Recover the Ward Stones from Jugnug, Wug, and Grunk, then use them to free Captain Kelra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55991] = { id = 55991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End to Beginnings", description = "You've done fine work within Exile's Reach, recruit. You should continue on to the Dragon Isles.\n\nI'm afraid I must change my plans and go back to Stormwind. I need to find out how the ogres found such powerful shadow magic.\n\nI'm sure we'll meet again. I can tell you've got many adventures ahead of you.", completion = "It's good to be back in Stormwind. \n\nI must report our mission's success to the king, but I have an idea for what you can do in the meantime...", objectives = "Speak with Kalecgos to travel to the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55992] = { id = 55992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungeon: Darkmaul Citadel", description = "You've slown down Gor'groth's efforts to control Kalecgos atop the citadel, but the ritual itself needs to be thwarted.\n\nYou must storm the citadel and stop him from completing the ritual. His dark magic is an affront to the Light.\n\nWe will need all the help we can get. Gor'groth's most elite lieutenants await within the citadel.", progress = "You must go and slay Gor'groth before it is too late!", completion = "It seems things are finally looking up for us. I think it's time we returned to Stormwind.", objectives = "Complete the dungeon, \"Darkmaul Citadel\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55993] = { id = 55993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Edge", description = "In the darkest cavern. Below the naga city. You will find them.\n\nCreepy little crabs with sharp and pointy spines. \n\nI think we can find a way to use them. Projectiles didn't work so well in water, but now...\n\nHarvest some for us!\n\nBe careful, some of them are much sneakier than they have any right to be.", progress = "Did you gather the spines?", completion = "Ouch! These might just do the trick!", objectives = "Collect 12 Chitterspine Spines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55994] = { id = 55994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Not Drink", description = "These troggs watch everything we do.  \n\nThey see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines!\n\nWe need that oil back, before they drink it all!", progress = "Get that oil back quick!", completion = "Ya done good work.", objectives = "Recover 12 containers of Stolen Oil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55995] = { id = 55995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Can Fix It", description = "<This drill rig looks capable of breaking through the nearby debris, but is clearly broken.\n\nIf you can collect the parts required, Prince Erazmin should be able to show you how to repair it.>", progress = "Us mechagnomes are always building something. Mechagon is littered with broken or half-completed construction projects.", completion = "Do these small parts appear insignificant to you?\n\nUse your imagination. Find their purpose. Give them value.", objectives = "Collect 40 Spare Parts and 1 Energy Cell from enemies in Junkwatt Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55997] = { id = 55997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry Hungry Hydras" }
quests[56000] = { id = 56000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We've Got Crabs!", description = "{name}, you're just in time. Everything's ready for the crab hunt!\n\nOkay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting?\n\nI'm going to level with you, {name}. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people.\n\nIf that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population!\n\nHow many innocent grub worms need to die before we do something, {name}?", progress = "How many innocent grub worms need to die before we do something, {name}?", completion = "That's quite the case of crabs you've got there, {name}. Well done! Please set it down behind the bar and I'll take care of the rest.", objectives = "Collect 12 Crackleclaw Crabs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56001] = { id = 56001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drunk Angry Murlocs", description = "Those no-good Bloodfins ran off with all of the beer!\n\nI've been experimenting with brews that only use ingredients native to Nazjatar, but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck.\n\nMy supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back.\n\nPlease recover the stolen lager from Bloodfin Village before it's too late!", progress = "Those no-good Bloodfins ran off with all of the beer!", completion = "Good work, {name}! You've recovered pretty much all of the stolen beer. Those Bloodfins are more trouble than they're worth!", objectives = "Collect 12 Ocean \"Infused\" Lagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56002] = { id = 56002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mgglurky's Mugglrgl", description = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back.\n\nI've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!\n\nI don't know about you, but I definitely don't want to be the main course tonight.\n\nThere were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", progress = "If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!", completion = "You've found it! So this is a mugglrgl? For some reason I thought it would be bigger. Mgglurky will be happy you returned it!", objectives = "Retrieve Mgglurky's Mugglrgl from Bloodfin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
