quests[56030] = { id = 56030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief's Order", description = "Champion, the Dark Lady summons you. The time has come to set her plan into motion.\n\nOur warships are ready to embark. The key to victory over the Alliance is within our grasp.\n\nMeet me in Zuldazar, aboard the Banshee's Wail. What we do next... we do for the Horde.", completion = "Ah, the final member of our crew has arrived.", objectives = "Meet with Nathanos Blightcaller on The Banshee's Wail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56031] = { id = 56031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wolf's Offensive", description = "Champion, Spymaster Shaw reports that the remains of the Horde fleet is preparing to depart.\n\nThey will be easy pickings for our superior forces. Let us seize this opportunity to eliminate their threat once and for all!\n\nPreparations are underway to set sail. Come to Boralus Harbor and meet with me upon the Wind's Redemption with all haste!", completion = "You're just in time, {name}. \nSpymaster Shaw was just informing me of some new intelligence we've recently learned about the Horde fleet.", objectives = "Meet with Genn Greymane on the Wind's Redemption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56032] = { id = 56032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Dozen" }
quests[56034] = { id = 56034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-sizing the Situation", description = "The Re-Sizer v9.0.1 barely works on inanimate objects. I have no idea what it will do to organic matter!\n\nBut if we do nothing, Wrathion will die!\n\nDesperate times call for massively experimental science, {name}.\n\nTake the Re-Sizer v9.0.1. I'll follow you around and calibrate it.\n\nWe're going to whip up a giant boar!", progress = "Be careful where you point the Re-Sizer v9.0.1. Make sure you're only using it on the boars in the immediate area.", completion = "I never thought I'd be so relieved to be face to face with a giant, scientifically enhanced boar.\n\nLet's go save my son.", objectives = "Use the Re-Sizer v9.0.1 on 3 Wandering Boars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56035] = { id = 56035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Most Delicious Clams", description = "This pool is filled with creepy fish. \n\nIt is also the home of some of the most delicious clams you will ever eat. Fresh water somehow mixes into the ocean water in this one part of Nazjatar, and that gives the meat a totally new flavor.\n\nEvery now and then, we come down here and collect them for our friends in Newhome.\n\nWe could sure use some help with all these extra mouths to feed!", progress = "Did you find enough?", completion = "Everyone is going to be so happy!\n\nThank you!", objectives = "Collect 10 Neptulian Clams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56036] = { id = 56036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Steamy Situation" }
quests[56037] = { id = 56037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Naga's Secrets", description = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite. \n\nWeapons of this power should never be in the hands of the naga.>", progress = "I recognize the craftsmanship. This is Priscilla Ashvane's work.  \n\nShe must have taught the naga how to forge Azerite weaponry, but why?", completion = "We cannot expect to succeed in any battle where our enemies are using Azerite weaponry. \n\nNo, we must find a way to even the playing field.", objectives = "Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56038] = { id = 56038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Working with Purpose", description = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. \n\nBefore you came along, it was my job to crawl around the cavern, cracking open clams. \n\nSo you see, you have some purpose, other than being a mindless sack of flesh.", progress = "Do you have them all?", completion = "Eager to please, aren't you?", objectives = "Collect 6 Iridescent Pearls from Chittershell Clams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56039] = { id = 56039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Can't Have Dull Weapons", description = "For a squid head, you sure are making my life easier. \n\nI guess you get to live long enough to complete another task. \n\nOur new weapons are forged from some foreign material that I don't quite trust. \n\nYou won't catch me sharpening any blades, but the work still needs to get done. \n\nGet to it!", completion = "<The weapons on the rack radiate with a familiar energy.>", objectives = "Find the special weaponry within Zanj'ir Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56041] = { id = 56041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give 'Em Shell" }
quests[56042] = { id = 56042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 7000", objectives = "OUTPUT: Please accept this GIFT. \n\nADMINISTER GIFT DISTRIBUTION PROTOCOL.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56043] = { id = 56043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send the Fleet", description = "This war has cost us dearly, but victory will soon be in our grasp.\n\nWhat remains of the Horde fleet has departed Zuldazar and our spies say that the Banshee Queen's hand sails at their helm.\n\nThis is our chance, {name}! With one strike we can eliminate what remains of their fleet and rid Azeroth of Blightcaller's filth once and for all!\n\nThe fleet is preparing to depart, report to the Harbormaster when you are ready to set sail.", completion = "Never could I have expected this...", objectives = "Speak to Harbormaster Cyrus Crestfall to set sail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56044] = { id = 56044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send the Fleet", description = "The Warchief has entrusted me with a mission of the highest priority, {name}.\n\nThe mission will succeed, of this there is no question, but to ensure that any obstacles I encounter are dealt with swiftly I once again have need of your particular skills.\n\nThe Zandalari have offered us use of their ships for this endeavor. Clear out whatever affairs you have remaining and report to Captain Rez'okun when you are ready to set sail.", completion = "An unexpected development, but it changes nothing.\n\nWe have our orders to carry out, {name}.", objectives = "Speak to Captain Rez'okun to set sail.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56045] = { id = 56045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Naga's Secrets", description = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite. \n\nWeapons of this power should never be in the hands of the naga.>", progress = "I recognize the craftsmanship. This is Priscilla Ashvane's work.  \n\nShe must have taught the naga how to forge Azerite weaponry, but why?", completion = "We cannot expect to succeed in any battle where our enemies are using Azerite weaponry. \n\nNo, we must find a way to even the playing field.", objectives = "Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
