quests[56047] = { id = 56047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Can't Have Dull Weapons", description = "For a squid head, you sure are making my life easier. \n\nI guess you get to live long enough to complete another task. \n\nOur new weapons are forged from some foreign material that I don't quite trust. \n\nYou won't catch me sharpening any blades, but the work still needs to get done. \n\nGet to it!", completion = "<The weapons on the rack radiate with a familiar energy.>", objectives = "Find the special weaponry within Zanj'ir Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56048] = { id = 56048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drowned Oracles" }
quests[56049] = { id = 56049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deck 'Em", description = "That ooze seems really hungry!\n\nHe ate my backpack, compass, pickaxe, and my hearthstone cards.\n\nGet my cards back!", progress = "I'm not leaving till I get my cards back!", completion = "Thank you! I'll grab my cards here, and meet you back in town!", objectives = "Recover Adalin's Hearthstone Cards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56050] = { id = 56050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "PvP Event: Battle for Nazjatar" }
quests[56053] = { id = 56053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Act", description = "Those of us with enough mechanization survived, but it didn't matter. Bondo Bigblock sold us out. In exchange for full mechanization, he built giant bots and attacked Rustbolt. \n\nHe will continue to act against us, till those few of us left are dead. \n\nWe must remove this threat immediately.", progress = "Will you help me deal with this threat?", completion = "We can start to rebuild now.", objectives = "Kill Bondo Bigblock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56056] = { id = 56056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror of the Depths" }
quests[56057] = { id = 56057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soulbinder" }
quests[56063] = { id = 56063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Tides", description = "A Tidemistress leads the naga in this area.\n\nShe is performing some damnable ritual outside, demanding sacrifices of our soldiers.\n\nStop her before more of our own meet a cruel fate.", completion = "With her death, the ritual is over. But there is not time for celebration.", objectives = "Slay Tidemistress Ethendriss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56064] = { id = 56064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: The Black Empire", description = "I cannot believe my eyes. The Black Empire is materializing right here in the Vale!\n\nWe must spring to action!", completion = "Thank goodness you arrived when you did! I still cannot believe that N'Zoth would strike at my very doorstep.\n\nThe pandaren will recount this tale for countless generations.", objectives = "Drive back the N'Zoth Assault in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56070] = { id = 56070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for the Venthyr", description = "Lord Denathrius has fallen under the sway of the Jailer. His betrayal of our people shall not stand.\n\nWe will show the Jailer that the venthyr are not to be underestimated... nor are you, Maw Walker. Slay his sub-lords. Let him know that he is now being hunted.", objectives = "Defeat the Jailer's lieutenants on floors 5 and 10 of the Jailer's Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56071] = { id = 56071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Synced Vibro Blade", description = "The wildly shaking blade reminds you of the blades the Rustbolt defenders use. No doubt someone will be able to fix it up.", objectives = "Give the De-Synced Vibro Blade to Ricket in Rustbolt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56072] = { id = 56072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Synced Vibro Blade", description = "The wildly shaking blade reminds you of the blades the Rustbolt defenders use. No doubt someone will be able to fix it up.", objectives = "Give the De-Synced Vibro Blade to Sapphronetta Flivvers in Rustbolt.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56074] = { id = 56074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Conduit" }
quests[56075] = { id = 56075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Power", description = "From the void these naga pull their strength. \n\nEach scroll they record, shared knowledge -- that knowledge is power.\n\nIt stands to reason, if we take away their knowledge, we steal their power.\n\nMy logic may be flawed, but let's do it anyway!", progress = "Did you get all of the scrolls?", completion = "Take away a little magic, get a little weaker.\n\nIf nothing else, we will win this war through erosion.", objectives = "Collect 8 Scrolls of Shirakess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56076] = { id = 56076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssal Ritual" }
quests[56078] = { id = 56078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Krill" }
quests[56080] = { id = 56080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Murlocs" }
quests[56081] = { id = 56081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Octo-Grab" }
quests[56082] = { id = 56082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bot Rampage", description = "Those bots have been attacking us from the moment we landed. We've got to hold this beach!\n\nMy expedition guards could use your help, {name}. Lend a hand, destroy bots on the beach and in the nearby woodlands.", progress = "The expedition guards could use your help!", completion = "They're still attacking, but we can handle it from here.", objectives = "15 attacking bots slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56083] = { id = 56083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsafe Work Conditions", description = "Those rampaging bots ain't lettin' up!\n\nWe're payin' good money for the best and brightest goblins on the planet, and I ain't gonna let some malfunctionin' machinery take 'em outta the shift schedule.\n\nThis is textbook unsafe working conditions, and the Greasemonkey Union reps are givin' me an earful for it. Protect the workers!", progress = "The greasemonkeys could use your help!", completion = "Ya done good work for a {race}.", objectives = "15 attacking bots slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56086] = { id = 56086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Holographic Digitalization Relay", description = "<This blueprint details how to build what appears to be some form of holographic teleporter.\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste.", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56087] = { id = 56087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Experimental Adventurer Augment", description = "<This blueprint details how to build what appears to be some form of ring... or maybe it's a trinket?\n\nYou should be able to upload the blueprint to Pascal-K1N6's database in Rustbolt.>", completion = "Have you recovered a new blueprint, my fleshy friend?\n\nI will add it to my database posthaste.", objectives = "Upload the blueprint to Pascal-K1N6's database.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56090] = { id = 56090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormstout Holdout" }
quests[56091] = { id = 56091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Usurper's Scent Gland", description = "When a new queen is born and old enough to start proliferating her own hive, she will leave the nest. Her scent will attract some of the hive to fly with her to their new home. This one likely never got the chance to do so, thanks to you.\n\nThe Hivemother will be interested in this item.", completion = "<The Hivemother quickly devours the scent gland and wiggles at you.>", objectives = "Take the Usurper's Scent Gland to the Honeyback Hivemother for a reward.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56092] = { id = 56092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hivethief's Jelly Stash", description = "This ettin was a well known and oft dreaded face among the bees of the Honeyback hive. Their jelly stores will benefit from his demise.\n\nThe Hivemother will be interested in this item.", completion = "<The Hivemother buzzes animatedly.>\n\nBzzz! Bzzz!", objectives = "Take the Hivethief's Jelly Stash to the Honeyback Hivemother for a reward.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56095] = { id = 56095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of Nar'anan", description = "Hey there, {race}. Mind helping me out?\n\nYou see, I found these pylons here and it seems they contain memories from a notable Highborne who lived here long ago.\n\nI can't get any closer to the rest of em' because of the snapdragons. Especially the terrormaws...\n\nCan you go and activate the pylons for me? We Tortollans love old things, and this is a potential goldmine!\n\nOh, and be sure to write down what you see!", completion = "Let me see what you got. \n\n<Collector Kojo reads your notes... slowly>\n\nI think we may have just found the origin of Snapdragons! Let's see what else we can learn.", objectives = "Activate the Memory Pylons in Nar'anan and witness what happened.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
